<section class="xc-s sec" id="check">
  <div class="wrap">
    <header class="sec__head sec__head--center" data-rv="scale">
      <p class="eyebrow">Quick check</p>
      <h2>How exposed is your site?</h2>
      <p class="sec__sub">Six yes or no questions. Nothing is sent anywhere.</p>
    </header>
    <form class="xc" id="xc" onsubmit="return false">
      <div class="xc__col" data-rv="left">
        <fieldset class="xc__q"><legend>Is the site empty at night?</legend><div class="xc__yn"><label class="xc__o"><input type="radio" name="x1" value="yes"><span>Yes</span></label><label class="xc__o"><input type="radio" name="x1" value="no"><span>No</span></label></div></fieldset>
        <fieldset class="xc__q"><legend>Do you store equipment or materials outside?</legend><div class="xc__yn"><label class="xc__o"><input type="radio" name="x2" value="yes"><span>Yes</span></label><label class="xc__o"><input type="radio" name="x2" value="no"><span>No</span></label></div></fieldset>
        <fieldset class="xc__q"><legend>Do you have working cameras and lights?</legend><div class="xc__yn"><label class="xc__o"><input type="radio" name="x3" value="yes"><span>Yes</span></label><label class="xc__o"><input type="radio" name="x3" value="no"><span>No</span></label></div></fieldset>
      </div>
      <div class="xc__mid" data-rv="scale">
        <div class="xc__ring">
          <svg viewBox="0 0 200 200" aria-hidden="true"><circle class="xc__bg" cx="100" cy="100" r="86"/><circle class="xc__fg" id="xc-ring" cx="100" cy="100" r="86" pathLength="1"/></svg>
          <div class="xc__num"><b id="xc-n">0</b><span>of 6 answered</span></div>
        </div>
        <div class="xc__res" aria-live="polite">
          <p class="xc__lvl" id="xc-lvl">Start with any question</p>
          <p id="xc-txt">Your result builds as you answer.</p>
          <a class="btn btn--gold" id="xc-go" href="#contact" data-cursor="Quote" hidden><span>Talk to us about it</span><svg aria-hidden="true"><use href="#i-arrow"/></svg></a>
          <p class="xc__note">A rough guide, not a security assessment.</p>
        </div>
      </div>
      <div class="xc__col" data-rv="right">
        <fieldset class="xc__q"><legend>Has anything gone missing in the last year?</legend><div class="xc__yn"><label class="xc__o"><input type="radio" name="x4" value="yes"><span>Yes</span></label><label class="xc__o"><input type="radio" name="x4" value="no"><span>No</span></label></div></fieldset>
        <fieldset class="xc__q"><legend>Do people come and go without being checked?</legend><div class="xc__yn"><label class="xc__o"><input type="radio" name="x5" value="yes"><span>Yes</span></label><label class="xc__o"><input type="radio" name="x5" value="no"><span>No</span></label></div></fieldset>
        <fieldset class="xc__q"><legend>Is your fire protection system offline at any point?</legend><div class="xc__yn"><label class="xc__o"><input type="radio" name="x6" value="yes"><span>Yes</span></label><label class="xc__o"><input type="radio" name="x6" value="no"><span>No</span></label></div></fieldset>
      </div>
    </form>
  </div>
</section>

<section class="plan sec" id="quote">
  <div class="wrap">
    <header class="sec__head" data-rv="clip">
      <p class="eyebrow">Coverage planner</p>
      <h2>Build your coverage plan</h2>
      <p class="sec__sub">Move the controls to match your site. You'll see the officer hours it adds up to, then send it to us for a real quote.</p>
    </header>
    <div class="pl" id="pl">
      <form class="pl__c" onsubmit="return false" data-rv="left">
        <fieldset class="pl__g"><legend>Site type</legend><div class="pl__os pl__os--site">
          <label class="pl-o"><input type="radio" name="pl-site" value="construction site" checked><span><svg aria-hidden="true"><use href="#i-crane"/></svg>Construction site</span></label>
          <label class="pl-o"><input type="radio" name="pl-site" value="farm or ranch"><span><svg aria-hidden="true"><use href="#i-leaf"/></svg>Farm / ranch</span></label>
          <label class="pl-o"><input type="radio" name="pl-site" value="residential community"><span><svg aria-hidden="true"><use href="#i-home"/></svg>Residential community</span></label>
          <label class="pl-o"><input type="radio" name="pl-site" value="event"><span><svg aria-hidden="true"><use href="#i-event"/></svg>Event</span></label>
          <label class="pl-o"><input type="radio" name="pl-site" value="industrial site"><span><svg aria-hidden="true"><use href="#i-factory"/></svg>Industrial</span></label>
          <label class="pl-o"><input type="radio" name="pl-site" value="healthcare facility"><span><svg aria-hidden="true"><use href="#i-medical"/></svg>Healthcare</span></label>
          <label class="pl-o"><input type="radio" name="pl-site" value="government site"><span><svg aria-hidden="true"><use href="#i-gov"/></svg>Government</span></label>
        </div></fieldset>
        <fieldset class="pl__g"><legend>Coverage type</legend><div class="pl__os">
          <label class="pl-o"><input type="radio" name="pl-cov" value="posted" checked><span>Posted officer</span></label>
          <label class="pl-o"><input type="radio" name="pl-cov" value="patrol"><span>Mobile patrol</span></label>
          <label class="pl-o"><input type="radio" name="pl-cov" value="fire"><span>Fire watch</span></label>
          <label class="pl-o"><input type="radio" name="pl-cov" value="access"><span>Access control</span></label>
        </div></fieldset>
        <fieldset class="pl__g"><legend>Armed or unarmed</legend><div class="pl__os pl__os--two">
          <label class="pl-o"><input type="radio" name="pl-arm" value="unarmed" checked><span>Unarmed</span></label>
          <label class="pl-o"><input type="radio" name="pl-arm" value="armed"><span>Armed</span></label>
        </div></fieldset>
        <div class="pl__g">
          <label class="pl__sl" for="pl-off"><span>Number of officers</span><output id="pl-off-o" for="pl-off">2</output></label>
          <input class="pl__r" type="range" id="pl-off" min="1" max="10" value="2">
        </div>
        <div class="pl__g">
          <label class="pl__sl" for="pl-hrs"><span>Hours per day</span><output id="pl-hrs-o" for="pl-hrs">12</output></label>
          <input class="pl__r" type="range" id="pl-hrs" min="1" max="24" value="12">
          <div class="pl__chips"><button class="pl-c" type="button" id="pl-night">Overnight 12h</button><button class="pl-c" type="button" id="pl-247">24/7</button></div>
        </div>
        <fieldset class="pl__g"><legend>Days per week</legend><div class="pl__days">
          <label class="pl-o"><input type="checkbox" name="pl-day" value="0" checked><span>Mon</span></label>
          <label class="pl-o"><input type="checkbox" name="pl-day" value="1" checked><span>Tue</span></label>
          <label class="pl-o"><input type="checkbox" name="pl-day" value="2" checked><span>Wed</span></label>
          <label class="pl-o"><input type="checkbox" name="pl-day" value="3" checked><span>Thu</span></label>
          <label class="pl-o"><input type="checkbox" name="pl-day" value="4" checked><span>Fri</span></label>
          <label class="pl-o"><input type="checkbox" name="pl-day" value="5"><span>Sat</span></label>
          <label class="pl-o"><input type="checkbox" name="pl-day" value="6"><span>Sun</span></label>
        </div>
        <div class="pl__chips"><button class="pl-c" type="button" id="pl-every">Every day</button></div>
        <p class="pl__hint" id="pl-hint" hidden>For one day, we'll use the first day you've picked.</p>
        </fieldset>
        <fieldset class="pl__g"><legend>How long</legend><div class="pl__os">
          <label class="pl-o"><input type="radio" name="pl-dur" value="day"><span>One day</span></label>
          <label class="pl-o"><input type="radio" name="pl-dur" value="week"><span>1 week</span></label>
          <label class="pl-o"><input type="radio" name="pl-dur" value="month"><span>1 month</span></label>
          <label class="pl-o"><input type="radio" name="pl-dur" value="ongoing" checked><span>Ongoing</span></label>
        </div></fieldset>
      </form>
